package com.aliucord.plugins.translate.backend

import com.aliucord.Http
import com.aliucord.plugins.translate.GOOGLE_TRANSLATE_API_URL
import com.aliucord.plugins.translate.TranslateResult
import com.aliucord.plugins.translate.USER_AGENT
import com.aliucord.plugins.translate.utils.TranslateUnescaper
import org.json.JSONArray

class GoogleTranslator : TranslatorBackend {

    override fun translate(
        text: String,
        sourceLang: String?,
        targetLang: String
    ): TranslateResult {
        val from = sourceLang?.ifEmpty { "auto" } ?: "auto"
        val url = Http.QueryBuilder(GOOGLE_TRANSLATE_API_URL).apply {
            append("client", "gtx")
            append("sl", from)
            append("tl", targetLang)
            append("dt", "t")
            append("q", text)
        }.toString()

        val response = Http.Request(url, "GET").apply {
            setHeader("Content-Type", "application/json")
            setHeader("User-Agent", USER_AGENT)
        }.execute()

        if (!response.ok()) {
            return TranslateResult.Error(
                errorCode = response.statusCode,
                errorText = when (response.statusCode) {
                    429 -> "Google Translate rate limited. Try again later."
                    else -> "Google Translate request failed."
                }
            )
        }

        val json   = JSONArray(response.text())
        val parts  = json.getJSONArray(0)
        val translated = buildString {
            for (i in 0 until parts.length()) {
                append(parts.getJSONArray(i).getString(0))
            }
        }.let { TranslateUnescaper.unescape(it) }

        return TranslateResult.Success(
            sourceLanguage    = json.optString(2, from),
            translatedLanguage = targetLang,
            sourceText        = text,
            translatedText    = translated
        )
    }
}

package com.aliucord.plugins.translate.backend

import com.aliucord.Http
import com.aliucord.plugins.translate.TranslateResult
import com.aliucord.plugins.translate.USER_AGENT
import org.json.JSONArray
import org.json.JSONObject

class LLMTranslator(
    private val baseUrl: String,
    private val apiKey: String,
    private val model: String,
    private val systemPrompt: String = DEFAULT_SYSTEM_PROMPT
) : TranslatorBackend {

    override fun translate(
        text: String,
        sourceLang: String?,
        targetLang: String
    ): TranslateResult {
        if (apiKey.isBlank() || baseUrl.isBlank()) {
            return TranslateResult.Error(
                errorText = "LLM API key or base URL not configured."
            )
        }

        val userPrompt = buildUserPrompt(text, sourceLang, targetLang)

        val requestBody = JSONObject().apply {
            put("model", model)
            put("temperature", 0.0)
            put("max_tokens", 2048)
            put("messages", JSONArray().apply {
                put(JSONObject().apply {
                    put("role", "system")
                    put("content", systemPrompt)
                })
                put(JSONObject().apply {
                    put("role", "user")
                    put("content", userPrompt)
                })
            })
        }

        val url = baseUrl.trimEnd('/') + "/v1/chat/completions"

        return try {
            val response = Http.Request(url, "POST").apply {
                setHeader("Content-Type", "application/json")
                setHeader("Authorization", "Bearer $apiKey")
                setHeader("User-Agent", USER_AGENT)
                setBody(requestBody.toString())
            }.execute()

            if (!response.ok()) {
                return TranslateResult.Error(
                    errorCode = response.statusCode,
                    errorText = "LLM API request failed: ${response.text().take(200)}"
                )
            }

            val json  = JSONObject(response.text())
            val content = json.getJSONArray("choices")
                .getJSONObject(0)
                .getJSONObject("message")
                .getString("content")
                .trim()

            TranslateResult.Success(
                sourceLanguage    = sourceLang ?: "auto",
                translatedLanguage = targetLang,
                sourceText        = text,
                translatedText    = content
            )
        } catch (e: Exception) {
            TranslateResult.Error(errorText = "LLM request exception: ${e.message}")
        }
    }

    private fun buildUserPrompt(text: String, sourceLang: String?, targetLang: String): String {
        val langPart = if (sourceLang != null && sourceLang != "auto")
            "from $sourceLang " else ""
        return "Translate ${langPart}to $targetLang. " +
            "Only return the translated text, nothing else.\n\n$text"
    }

    companion object {
        const val DEFAULT_SYSTEM_PROMPT =
            "You are a professional translator. " +
            "Only output the translated text, no explanations."
    }
}

package com.aliucord.plugins.translate.utils

import java.io.StringWriter
import java.io.Writer

object TranslateUnescaper {

    fun unescape(input: String): String {
        val writer = StringWriter(input.length * 2)
        var pos = 0
        val len = input.length

        while (pos < len) {
            val consumed = translate(input, pos, writer)
            if (consumed == 0) {
                val c1 = input[pos]
                writer.write(c1.code)
                pos++
                if (Character.isHighSurrogate(c1) && pos < len) {
                    val c2 = input[pos]
                    if (Character.isLowSurrogate(c2)) {
                        writer.write(c2.code)
                        pos++
                    }
                }
                continue
            }
            for (pt in 0 until consumed) {
                pos += Character.charCount(Character.codePointAt(input, pos))
            }
        }
        return writer.toString()
    }

    private fun translate(input: String, index: Int, writer: Writer): Int {
        if (input[index] == '\\' && index + 1 < input.length && input[index + 1] == 'u') {
            var i = 2
            while (index + i < input.length && input[index + i] == 'u') i++
            if (index + i < input.length && input[index + i] == '+') i++

            if (index + i + 4 <= input.length) {
                val hex = input.subSequence(index + i, index + i + 4)
                try {
                    writer.write(hex.toString().toInt(16).toChar().code)
                } catch (_: NumberFormatException) { }
                return i + 4
            }
        }
        return 0
    }
}

package com.aliucord.plugins.translate.utils

import com.aliucord.CollectionUtils
import com.discord.widgets.chat.list.WidgetChatList
import com.discord.widgets.chat.list.entries.MessageEntry

/**
 * 自实现的 rerenderMessage，直接操作 adapter，不依赖 Aliucord 内部 API。
 * 用于翻译完成后强制刷新单条消息视图。
 */
fun WidgetChatList.forceRerenderMessage(messageId: Long) {
    try {
        val adapter = WidgetChatList.`access$getAdapter$p`(this)
        val data = adapter.internalData
        val idx = CollectionUtils.findIndex(data) { entry ->
            entry is MessageEntry && entry.message.id == messageId
        }
        if (idx != -1) adapter.notifyItemChanged(idx)
    } catch (_: Exception) {
        // 如果内部 API 变动，静默忽略，不影响主流程
    }
}
